// A class with a resource that is expensive to copy.
class StringTable {
public:
    // A user-declared destructor, e.g., for logging.
    ~StringTable() { /* custom logic */ }

    // The presence of this destructor SUPPRESSES the implicit
    // generation of the move constructor and move assignment operator.

    // The copy operations are still generated (though their generation
    // in this context is deprecated).
private:
    std::map<int, std::string> data; // Expensive to copy.
};

void demo() {
    StringTable st1;
    // This looks like a move, but it silently invokes the copy constructor
    // because the move constructor was suppressed by the destructor.
    StringTable st2 = std::move(st1);
}
